import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    private static final long[] a = new long[9];
    private static final SHelper helper = new SHelper();

    public static void main(String[] args) throws IOException {
        helper.init();

        for (int k = 1; k <= 8; k++) {
            long l = (1L << k) - 1;
            long r = 1L << (k - 1);
            a[k] = l * r;
        }

        long n = helper.readLong();
        for (int k = 8; k >= 1; k--) {
            if (n >= a[k] && n % a[k] == 0) {
                System.out.println(a[k]);
                return;
            }
        }
    }

    private static class SHelper {
        private BufferedInputStream input;

        void init() {
            input = new BufferedInputStream(System.in);
        }

        long readLong() throws IOException {
            int c;
            do {
                c = input.read();
            } while (c <= ' ' && c != -1);

            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = input.read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = input.read();
            }
            return negative ? -value : value;
        }
    }
}

